const crypto = require('crypto');

// Extract the raw body from the binary field
const binaryData = await this.helpers.getBinaryDataBuffer(0, 'data');
const rawBody = binaryData.toString('utf8');

// Extract headers and the Shopify HMAC
const headers = $input.first().json.headers || {};
const shopifyHmac = headers['x-shopify-hmac-sha256'];

if (!shopifyHmac) {
  throw new Error('Missing X-Shopify-Hmac-Sha256 header');
}

// Use the client secret from the credential (replace with your actual secret)
const secretKey = 'YOUR_SHOPIFY_CLIENT_SECRET';

// Compute the HMAC-SHA256 signature
const computedHmac = crypto
  .createHmac('sha256', secretKey)
  .update(rawBody, 'utf8')
  .digest('base64');

// Compare the computed signature with the received signature
if (computedHmac !== shopifyHmac) {
  throw new Error('HMAC validation failed. Request is not from Shopify.');
}

// Parse the JSON body once verification succeeds
const orderData = JSON.parse(rawBody);

return [{
  json: {
    verified: true,
    order: orderData,
    headers: headers,
    topic: headers['x-shopify-topic'] || null,
    webhook_id: headers['x-shopify-webhook-id'] || null
  }
}];

// Reshape the verified Shopify order into a clean payload for the email and the audit log.
// All defensive fallbacks are in place so a missing customer or missing line_items does not throw.

const results = [];

for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];
  const order = item.json.order || {};
  const headers = item.json.webhook_headers 
  || item.json.headers 
  || ($('Receive Shopify Order').first().json.headers || {});
  const verified = item.json.verified === true;
  const webhookId = item.json.webhook_id || headers['x-shopify-webhook-id'] || null;
  const topic = item.json.topic || headers['x-shopify-topic'] || null;
  const shopDomain = headers['x-shopify-shop-domain'] || 'YOUR_SHOPIFY_SHOP';

  // Customer fallback: prefer nested customer object, fall back to top-level email
  let customerEmail = null;
  if (order.customer && order.customer.email) {
    customerEmail = order.customer.email;
  } else if (order.email) {
    customerEmail = order.email;
  }

  // Customer name: only if the nested customer object exists
  let customerName = null;
  if (order.customer && (order.customer.first_name || order.customer.last_name)) {
    const parts = [order.customer.first_name, order.customer.last_name].filter(Boolean);
    customerName = parts.length > 0 ? parts.join(' ') : null;
  }

  // Line items: trim to title, quantity, price. Defensive against missing or non-array.
  const rawLineItems = Array.isArray(order.line_items) ? order.line_items : [];
  const lineItems = rawLineItems.map(li => ({
    title: li.title || 'Item',
    quantity: Number(li.quantity) || 0,
    price: Number(li.price) || 0
  }));

  // Total: numeric for downstream, formatted string for the email
  const totalPriceNumber = Number(order.total_price);
  const totalPriceSafe = isNaN(totalPriceNumber) ? 0 : totalPriceNumber;
  const currency = order.currency || 'USD';
  const totalPriceDisplay = totalPriceSafe.toFixed(2) + ' ' + currency;

  results.push({
    json: {
      // Extracted fields
      order_id: order.id || null,
      order_number: order.order_number ? String(order.order_number) : null,
      customer_email: customerEmail,
      customer_name: customerName,
      total_price: totalPriceSafe,
      total_price_display: totalPriceDisplay,
      currency: currency,
      financial_status: order.financial_status || null,
      line_items: lineItems,
      created_at: order.created_at || null,
      shop_domain: shopDomain,

      // Verification context carried forward
      verified: verified,
      webhook_id: webhookId,
      topic: topic,

      // Preserve raw data for the audit log
      order_raw: order,
      webhook_headers: headers
    }
  });
}

return results;

// Build the HTML and plain-text confirmation email bodies.
// All styles are inline. No <style> blocks. No external assets.
// User content is HTML-escaped before insertion.

const results = [];

// HTML entity escaping for safe interpolation into the email template
function escHtml(s) {
  if (s === null || s === undefined) return '';
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

for (let i = 0; i < $input.all().length; i++) {
  const d = $input.all()[i].json;

  // Subject line: prefer order_number, fall back to order_id
  const orderLabel = d.order_number ? d.order_number : String(d.order_id);
  const subject = 'Order ' + orderLabel + ' confirmed';

  // Customer greeting
  const greeting = d.customer_name ? ('Hi ' + d.customer_name + ',') : 'Hi,';

  // Line items rows for the HTML table
  const lineItemRowsHtml = d.line_items.map(function (li) {
    return '' +
      '<tr>' +
        '<td style="padding:12px 8px;border-bottom:1px solid #eaeaea;font-size:14px;color:#333333;text-align:left;">' +
          escHtml(li.title) +
        '</td>' +
        '<td style="padding:12px 8px;border-bottom:1px solid #eaeaea;font-size:14px;color:#333333;text-align:center;">' +
          li.quantity +
        '</td>' +
        '<td style="padding:12px 8px;border-bottom:1px solid #eaeaea;font-size:14px;color:#333333;text-align:right;">' +
          li.price.toFixed(2) + ' ' + escHtml(d.currency) +
        '</td>' +
      '</tr>';
  }).join('');

  // Line items for the plain-text body
  const lineItemsText = d.line_items.map(function (li) {
    return '  - ' + li.title + ' x' + li.quantity + '  ' + li.price.toFixed(2) + ' ' + d.currency;
  }).join('\n');

  // HTML body
  const html_body = '' +
    '<!DOCTYPE html>' +
    '<html lang="en">' +
    '<head>' +
      '<meta charset="utf-8">' +
      '<meta name="viewport" content="width=device-width,initial-scale=1">' +
      '<title>' + escHtml(subject) + '</title>' +
    '</head>' +
    '<body style="margin:0;padding:0;background-color:#f4f4f5;font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',Roboto,Arial,sans-serif;">' +
      '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color:#f4f4f5;">' +
        '<tr>' +
          '<td align="center" style="padding:24px 12px;">' +
            '<table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="max-width:600px;width:100%;background-color:#ffffff;border-radius:8px;overflow:hidden;">' +
              '<tr>' +
                '<td style="background-color:#111827;padding:24px;text-align:center;">' +
                  '<span style="color:#ffffff;font-size:18px;font-weight:600;letter-spacing:0.02em;">' + escHtml(d.shop_domain) + '</span>' +
                '</td>' +
              '</tr>' +
              '<tr>' +
                '<td style="padding:32px 24px 8px 24px;">' +
                  '<h1 style="margin:0 0 16px 0;font-size:22px;line-height:1.3;color:#111827;font-weight:600;">Order confirmed</h1>' +
                  '<p style="margin:0 0 8px 0;font-size:15px;line-height:1.5;color:#374151;">' + escHtml(greeting) + '</p>' +
                  '<p style="margin:0 0 24px 0;font-size:15px;line-height:1.5;color:#374151;">Thanks for your order. Here is what we received:</p>' +
                '</td>' +
              '</tr>' +
              '<tr>' +
                '<td style="padding:0 24px;">' +
                  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">' +
                    '<tr>' +
                      '<td style="padding:8px;font-size:12px;color:#6b7280;text-transform:uppercase;letter-spacing:0.04em;text-align:left;">Item</td>' +
                      '<td style="padding:8px;font-size:12px;color:#6b7280;text-transform:uppercase;letter-spacing:0.04em;text-align:center;">Qty</td>' +
                      '<td style="padding:8px;font-size:12px;color:#6b7280;text-transform:uppercase;letter-spacing:0.04em;text-align:right;">Price</td>' +
                    '</tr>' +
                    lineItemRowsHtml +
                  '</table>' +
                '</td>' +
              '</tr>' +
              '<tr>' +
                '<td style="padding:24px;">' +
                  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">' +
                    '<tr>' +
                      '<td style="padding:8px;font-size:15px;color:#111827;font-weight:600;text-align:right;">Total</td>' +
                      '<td style="padding:8px;font-size:15px;color:#111827;font-weight:600;text-align:right;width:120px;">' + escHtml(d.total_price_display) + '</td>' +
                    '</tr>' +
                  '</table>' +
                '</td>' +
              '</tr>' +
              '<tr>' +
                '<td style="padding:0 24px 32px 24px;">' +
                  '<p style="margin:0;font-size:14px;line-height:1.5;color:#6b7280;">' +
                    'Order reference: ' + escHtml(orderLabel) +
                  '</p>' +
                '</td>' +
              '</tr>' +
              '<tr>' +
                '<td style="background-color:#f9fafb;padding:20px 24px;border-top:1px solid #e5e7eb;">' +
                  '<p style="margin:0;font-size:12px;line-height:1.5;color:#9ca3af;text-align:center;">' +
                    'This message was sent automatically by ' + escHtml(d.shop_domain) +
                  '</p>' +
                '</td>' +
              '</tr>' +
            '</table>' +
          '</td>' +
        '</tr>' +
      '</table>' +
    '</body>' +
    '</html>';

  // Plain-text fallback
  const text_body = '' +
    subject + '\n\n' +
    greeting + '\n\n' +
    'Thanks for your order. Here is what we received:\n\n' +
    lineItemsText + '\n\n' +
    'Total: ' + d.total_price_display + '\n\n' +
    'Order reference: ' + orderLabel + '\n\n' +
    'This message was sent automatically by ' + d.shop_domain + '\n';

  results.push({
    json: Object.assign({}, d, {
      subject: subject,
      html_body: html_body,
      text_body: text_body
    })
  });
}

return results;

// Precompute the full Resend API request body as a JSON string.
// The html_body contains newlines and quotes that break inline JSON interpolation.

const results = [];

for (let i = 0; i < $input.all().length; i++) {
  const d = $input.all()[i].json;

  const body = {
    from: 'onboarding@resend.dev',
    to: d.customer_email,
    subject: d.subject,
    html: d.html_body,
    text: d.text_body
  };

  results.push({
    json: Object.assign({}, d, {
      body_string: JSON.stringify(body)
    })
  });
}

return results;
